tool_input.command:
G=$(powershell -c "[guid]::NewGuid().ToString()" | tr -d '\r') && python - "$G" <<'EOF'
import sys
g=sys.argv[1]
s=open('Collection.cs',encoding='utf-8-sig').read()
new='''
    [GrasshopperCollection("Bench", "Data")]
    public interface IMyAsyncPack : IBettaCollection
    {
        [GrasshopperMethod("Async Stats", "Mean and standard deviation of a list of numbers, computed asynchronously", Guid = "%s")]
        Task<(double Mean, double StdDev)> AsyncStats(
            [GrasshopperParameter("Values")] List<double> values,
            CancellationToken cancellationToken);
    }

    public class MyAsyncPack : IMyAsyncPack
    {
        public Task<(double Mean, double StdDev)> AsyncStats(List<double> values, CancellationToken cancellationToken)
        {
            return Task.Run(() =>
            {
                if (values == null || values.Count == 0) return (0.0, 0.0);
                double sum = 0;
                foreach (var v in values)
                {
                    cancellationToken.ThrowIfCancellationRequested();
                    sum += v;
                }
                double mean = sum / values.Count;
                double sq = 0;
                foreach (var v in values)
                {
                    cancellationToken.ThrowIfCancellationRequested();
                    sq += (v - mean) * (v - mean);
                }
                return (mean, Math.Sqrt(sq / values.Count));
            }, cancellationToken);
        }
    }
''' % g
i=s.rindex('}')
s=s[:i].rstrip('\n')+'\n'+new+'}\n'
s=s.replace('using Betta.Interfaces;','using Betta.Interfaces;\nusing System;\nusing System.Collections.Generic;\nusing System.Threading;\nusing System.Threading.Tasks;',1)
open('Collection.cs','w',encoding='utf-8').write(s)
EOF
dotnet build 2>&1 | tail -5
